/**
 * Durable, bounded export artifacts for browser and desktop hosts.
 *
 * The store deliberately keeps generated bytes separate from the editor's
 * document library. Metadata never contains file bytes, and download
 * requests are recorded without claiming that a browser saved the file.
 */

export const ARTIFACT_STORAGE_VERSION = 1;
export const DEFAULT_ARTIFACT_TTL_MS = 24 * 60 * 60 * 1000;
export const DEFAULT_ARTIFACT_BUDGET = 128 * 1024 * 1024;
export const DEFAULT_ARTIFACT_LIMIT = 64;
export const MAX_ARTIFACT_BYTES = 64 * 1024 * 1024;

const STORE_NAME = "artifacts";
const request = operation => new Promise((resolve, reject) => {
  operation.onsuccess = () => resolve(operation.result);
  operation.onerror = () => reject(operation.error);
});
const complete = transaction => new Promise((resolve, reject) => {
  transaction.oncomplete = resolve;
  transaction.onabort = () => reject(transaction.error || new Error("The artifact transaction was aborted."));
  transaction.onerror = () => {};
});

export class ArtifactStoreError extends Error {
  constructor(message, code = "ARTIFACT_STORE_FAILED", cause) {
    super(message, { cause });
    this.name = "ArtifactStoreError";
    this.code = code;
  }
}

function fail(message, code = "INVALID_ARTIFACT") {
  throw new ArtifactStoreError(message, code);
}

function asBytes(value) {
  if (value instanceof Uint8Array) return value;
  if (value instanceof ArrayBuffer) return new Uint8Array(value);
  if (ArrayBuffer.isView(value)) return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  return null;
}

async function bytesFrom(value) {
  const bytes = asBytes(value);
  if (bytes) return Uint8Array.from(bytes);
  if (typeof Blob !== "undefined" && value instanceof Blob) return new Uint8Array(await value.arrayBuffer());
  fail("Artifact data must be a Blob, ArrayBuffer, or byte array.");
}

function hex(bytes) { return Array.from(bytes, value => value.toString(16).padStart(2, "0")).join(""); }

function id() {
  if (typeof crypto?.randomUUID === "function") return `artifact-${crypto.randomUUID()}`;
  return `artifact-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

function metadata(record) {
  return {
    artifactId: record.artifactId,
    name: record.name,
    mime: record.mime,
    bytes: record.bytes,
    sha256: record.sha256,
    createdAt: record.createdAt,
    expiresAt: record.expiresAt,
    storedAt: record.storedAt,
    lifecycle: {
      producedAt: record.producedAt,
      savedAt: record.savedAt,
      downloadRequestedAt: record.downloadRequestedAt,
      downloadCompletedAt: null,
    },
  };
}

function safeName(value) {
  const leaf = [...(String(value).trim().replace(/\\/g, "/").split("/").at(-1) ?? "")].map(character => {
    const code = character.charCodeAt(0);
    return code < 32 || code === 127 ? "_" : character;
  }).join("");
  if (!leaf || leaf === "." || leaf === "..") fail("Artifact name is invalid.");
  return leaf.slice(0, 240);
}

function validId(value) {
  if (typeof value !== "string" || !value || value.length > 200) fail("Artifact ID is invalid.");
  return value;
}

/** Open the artifact store. The options are injectable for deterministic tests. */
export async function openArtifactStore(options = {}) {
  const factory = options.indexedDB ?? globalThis.indexedDB;
  const cryptoImpl = options.crypto ?? globalThis.crypto;
  if (!factory || !cryptoImpl?.subtle) throw new ArtifactStoreError("Durable artifact storage is unavailable.", "UNAVAILABLE");
  const db = await request((() => {
    const opening = factory.open(options.name ?? "pixelwall-artifacts-v1", ARTIFACT_STORAGE_VERSION);
    opening.onupgradeneeded = () => {
      if (!opening.result.objectStoreNames.contains(STORE_NAME)) opening.result.createObjectStore(STORE_NAME, { keyPath: "artifactId" });
    };
    return opening;
  })()).catch(error => { throw new ArtifactStoreError("The artifact store could not be opened.", "OPEN_FAILED", error); });
  const now = options.now ?? Date.now;
  const budgetBytes = Math.max(1, options.budgetBytes ?? DEFAULT_ARTIFACT_BUDGET);
  const artifactLimit = Math.max(1, options.maxArtifacts ?? DEFAULT_ARTIFACT_LIMIT);
  const defaultTtlMs = Math.max(1, options.ttlMs ?? DEFAULT_ARTIFACT_TTL_MS);
  let sequence = Promise.resolve();
  const serialize = operation => { const next = sequence.then(operation); sequence = next.catch(() => {}); return next; };
  async function read(fn) {
    const tx = db.transaction(STORE_NAME, "readonly");
    const finished = complete(tx);
    try { const result = await fn(tx.objectStore(STORE_NAME)); await finished; return result; }
    catch (error) { await finished.catch(() => {}); throw error; }
  }
  async function write(fn) {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const finished = complete(tx);
    try { const result = await fn(tx.objectStore(STORE_NAME)); await finished; return result; }
    catch (error) { try { tx.abort(); } catch { /* The transaction may already be finished. */ } await finished.catch(() => {}); throw error; }
  }
  function prune(store, entries, timestamp, incomingBytes = 0, incomingId = null) {
    const retained = [];
    for (const entry of entries) {
      if (entry.expiresAt <= timestamp || entry.artifactId === incomingId) store.delete(entry.artifactId);
      else retained.push(entry);
    }
    retained.sort((a, b) => a.createdAt - b.createdAt || a.artifactId.localeCompare(b.artifactId));
    let total = retained.reduce((sum, entry) => sum + entry.bytes, 0) + incomingBytes;
    const incomingCount = incomingBytes > 0 ? 1 : 0;
    while (retained.length + incomingCount > artifactLimit || total > budgetBytes) {
      const removed = retained.shift();
      if (!removed) break;
      total -= removed.bytes;
      store.delete(removed.artifactId);
    }
    return retained;
  }
  const store = {
    /** @param {{ artifactId?: string, name?: string, mime?: string, data?: Blob|ArrayBuffer|Uint8Array, bytes?: Blob|ArrayBuffer|Uint8Array, ttlMs?: number }} options */
    async putArtifact({ artifactId = id(), name, mime = "application/octet-stream", data, bytes, ttlMs = defaultTtlMs } = {}) {
      return serialize(async () => {
        const payload = await bytesFrom(data ?? bytes);
        if (!payload.byteLength || payload.byteLength > MAX_ARTIFACT_BYTES) fail(`Artifact must be between 1 byte and ${MAX_ARTIFACT_BYTES} bytes.`, "SIZE_LIMIT");
        if (typeof name !== "string" || !name.trim() || name.length > 240) fail("Artifact name is invalid.");
        if (typeof mime !== "string" || !mime.trim() || mime.length > 200) fail("Artifact MIME type is invalid.");
        if (!Number.isFinite(ttlMs) || ttlMs <= 0) fail("Artifact TTL must be positive.");
        const createdAt = now();
        const record = {
          artifactId: validId(artifactId), name: safeName(name), mime: mime.trim(),
          bytes: payload.byteLength,
          sha256: hex(new Uint8Array(await cryptoImpl.subtle.digest("SHA-256", payload))),
          createdAt, expiresAt: createdAt + Math.min(ttlMs, 30 * 24 * 60 * 60 * 1000), storedAt: createdAt,
          producedAt: createdAt, savedAt: createdAt, downloadRequestedAt: null,
          data: typeof Blob !== "undefined" ? new Blob([payload], { type: mime }) : payload,
        };
        if (record.bytes > budgetBytes) fail("Artifact exceeds the configured storage budget.", "BUDGET_EXCEEDED");
        await write(async objectStore => {
          const existing = (await request(objectStore.getAll())).filter(entry => entry.artifactId !== record.artifactId);
          prune(objectStore, existing, createdAt, record.bytes, record.artifactId);
          objectStore.put(record);
        });
        return metadata(record);
      });
    },
    async listArtifacts() {
      return serialize(async () => {
        const timestamp = now();
        let entries;
        await write(async objectStore => {
          entries = await request(objectStore.getAll());
          entries = prune(objectStore, entries, timestamp);
        });
        return entries.filter(entry => entry.expiresAt > timestamp).sort((a, b) => b.createdAt - a.createdAt).map(metadata);
      });
    },
    async getArtifact(artifactId) {
      validId(artifactId);
      return serialize(async () => {
        const entry = await read(objectStore => request(objectStore.get(artifactId)));
        if (!entry) return null;
        if (entry.expiresAt <= now()) { await write(objectStore => { objectStore.delete(artifactId); }); return null; }
        const copy = metadata(entry);
        const blob = entry.data instanceof Blob ? entry.data : new Blob([entry.data], { type: entry.mime });
        return { metadata: copy, blob };
      });
    },
    async markDownloadRequested(artifactId, requestedAt = now()) {
      validId(artifactId);
      return serialize(async () => {
        const entry = await read(objectStore => request(objectStore.get(artifactId)));
        if (!entry || entry.expiresAt <= now()) { if (entry) await write(objectStore => { objectStore.delete(artifactId); }); return null; }
        entry.downloadRequestedAt = requestedAt;
        await write(objectStore => { objectStore.put(entry); });
        return metadata(entry);
      });
    },
    async removeArtifact(artifactId) {
      validId(artifactId);
      return serialize(async () => {
        const entry = await read(objectStore => request(objectStore.get(artifactId)));
        if (!entry) return false;
        await write(objectStore => { objectStore.delete(artifactId); });
        return true;
      });
    },
    close: () => db.close(),
  };
  return store;
}

